import{d as g,C as t,o as h,c as d,j as i,a,E as e,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"中庸·第2章","description":"《中庸》第 2 章——仲尼以君子与小人相对：君子而时中，小人而无忌惮。中庸之名自此正式立起。","frontmatter":{"title":"中庸·第2章","description":"《中庸》第 2 章——仲尼以君子与小人相对：君子而时中，小人而无忌惮。中庸之名自此正式立起。","category":"guide","aliases":["第2章","中庸第2章","君子中庸"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-02.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-02.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-02.md"},z=g({...m,setup(p){const r=[{id:"zongshuo",label:"君子中庸 · 小人反中庸",showLabel:!0,sentences:[["仲尼曰：“",{text:"君子",glossary:"junzi"},"中庸，",{text:"小人",glossary:"xiaoren"},{text:"反",glossary:"fan"},"中庸。”"]],note:"「仲尼曰」——引孔子之言立论。君子能守「中庸」（不偏不倚、无过不及的恰当与恒常；庸＝常），小人则「反」（违背）中庸。两句对举，点出二者的分野。"},{id:"fenshuo",label:"君子而时中 · 小人而无忌惮",showLabel:!0,sentences:[["“君子之中庸也，君子而",{text:"时中",glossary:"shizhong"},"；小人之反中庸也，小人而",{text:"无忌惮",glossary:"wujidan"},"也。”"]],note:"承上句分说其所以然：君子之所以能中庸，在有君子之德而又能「时中」——随时而处中；小人之所以反中庸，在有小人之心而又「无忌惮」——无所畏惮。朱熹注：「君子之所以为中庸者，以其有君子之德，而又能随时以处中也。」"}],s=[{id:"zhongni",term:"仲尼",pinyin:"zhòng ní",meaning:"孔子的字。孔子名丘，字仲尼。《中庸》引孔子之言以立论，此章起首标「仲尼曰」。"},{id:"junzi",term:"君子",pinyin:"jūn zǐ",meaning:"成德之人。此处指德性已成者，重在德，不重在位。"},{id:"xiaoren",term:"小人",pinyin:"xiǎo rén",meaning:"与君子相对，指德性未成、溺于私欲之人。此处非指身份地位。"},{id:"zhongyong",term:"中庸",pinyin:"zhōng yōng",meaning:"不偏不倚、无过不及的恰当与恒常。庸：常、平常。"},{id:"fan",term:"反",pinyin:"fǎn",meaning:"违背、相反。"},{id:"shizhong",term:"时中",pinyin:"shí zhōng",meaning:"随时而处中。朱注：「君子之所以为中庸者，以其有君子之德，而又能随时以处中也。」"},{id:"wujidan",term:"无忌惮",pinyin:"wú jì dàn",meaning:"无所畏惮、毫无忌惮。朱注：「小人之所以反中庸者，以其有小人之心，而又无所忌惮也。」"}];return(c,n)=>{const l=t("DaoTextReading"),o=t("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第2章",tabindex:"-1"},[a("中庸·第2章 "),i("a",{class:"header-anchor",href:"#中庸·第2章","aria-label":'Permalink to "中庸·第2章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,"此章承首章立「中庸」之名，以君子与小人对举，点出二者的分野——一个「时中」，一个「无忌惮」。默认竹简沉浸通读；切「经典阅读」可点生词。",-1)),e(l,{colophon:"君子中庸 · 时中与无忌惮",tone:"ink",sections:r,glossary:s,"default-mode":"slips","aria-label":"中庸·第2章 原文"}),n[3]||(n[3]=i("blockquote",null,[i("p",null,[i("strong",null,"版本异文"),a("：此句一作「"),i("strong",null,"小人之中庸也"),a("」。朱熹《章句》云：「王肃本作『小人之反中庸也』，程子亦以为然，今从之。」——即今传章句本作「反」；作「小人之中庸也」者，谓小人亦自有其所以为「中庸」，两读皆可与下文「无忌惮」相贯。")])],-1)),n[4]||(n[4]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),e(o,{items:[{term:"仲尼",pinyin:["zhòng","ní"],meaning:"孔子的字。孔子名丘，字仲尼。《中庸》引孔子之言以立论。"},{term:"君子",pinyin:["jūn","zǐ"],meaning:"成德之人。此处指德性已成者，重在德，不重在位。"},{term:"小人",pinyin:["xiǎo","rén"],meaning:"与君子相对，指德性未成、溺于私欲之人。此处非指身份地位。"},{term:"中庸",pinyin:["zhōng","yōng"],meaning:"不偏不倚、无过不及的恰当与恒常。庸：常、平常。"},{term:"反",pinyin:["fǎn"],meaning:"违背、相反。「小人反中庸」，即与中庸相背而行。"}]}),e(o,{items:[{term:"时中",pinyin:["shí","zhōng"],meaning:"随时而处中。朱注：「君子之所以为中庸者，以其有君子之德，而又能随时以处中也。」——即有德，又能在不同时候都处得其当。"},{term:"无忌惮",pinyin:["wú","jì","dàn"],meaning:"无所畏惮、毫无忌惮。朱注：「小人之所以反中庸者，以其有小人之心，而又无所忌惮也。」"}]}),n[5]||(n[5]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>君子中庸 · 小人反中庸</strong>：孔子说：君子行中庸，小人违背中庸。</p><p><strong>君子而时中 · 小人而无忌惮</strong>：君子的中庸，在于他是君子而又能随时处中；小人的违背中庸，在于他是小人而又无所忌惮。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第二章只有两句话，却把「中庸」这个名字正式立了起来。它以<strong>君子与小人</strong>对举，指出二者的分野不在别的，正在两个字上：一个是「<strong>时中</strong>」，一个是「<strong>无忌惮</strong>」。</p><p>「时中」是君子的中庸——不只是守着中道，而是<strong>随时都处得其当</strong>；「无忌惮」是小人的反中庸——不是偏了一点，而是<strong>毫无畏惮</strong>，所以任意而行。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它把「中」落到了时间上</strong>：首章讲「未发之中／发而中节」（体与用），本章补上一层「时中」——同一个道理，在不同的时候有不同的恰当。中庸不是固定中点，是<strong>该在哪就在哪</strong>。</li><li><strong>它指出反中庸的根不在「不懂」，而在「不畏」</strong>：朱注把两面并列——「有小人之心」（德未成）与「无所忌惮」（无所畏惮）。前者是认识与修养问题，后者是<strong>失去了敬畏</strong>。</li><li><strong>它给出了一组极简的对照</strong>：君子—时中／小人—无忌惮。这一组对照贯穿全篇，后面的「民鲜能久」「择乎中庸而不能守」都是在展开这一章。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>别把中庸当固定标准</strong>：同一件事，甲时该如此、乙时该如彼；「时中」问的不是「中间在哪」，而是「此刻的恰当在哪」。</li><li><strong>看反中庸的根</strong>：真正的失守往往不是不懂道理，而是<strong>不再有所畏惮</strong>——对规则、对后果、对他人、对自己。</li><li><strong>自省两问</strong>：我的「随和」是时中，还是不敢坚持？我的「坚持」是守中，还是无忌惮？</li><li><strong>接手首章</strong>：首章说「可离，非道也」；本章说小人「无忌惮」——一个是「离不开」，一个是「无所谓」，正成对照。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子说：君子行中庸，小人反中庸。差别在哪？</p><p><strong>君子的中庸，叫「时中」</strong>——他有德，而且能在不同的时候都站到恰当的位置上。不是守着一条固定的中线不动，而是随时知道此刻的分寸在哪里。</p><p><strong>小人的反中庸，叫「无忌惮」</strong>——不是他偏了多少度，而是他心里没有敬畏：对限度无所谓，对后果无所谓，对别人也无所谓。所以不是「不懂中庸」，而是「不怕」。</p><p>一句话：<strong>中庸不是中间值，而是「该在哪就在哪」；反中庸也不是偏差，而是无所畏惮。</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「时中」与首章的「未发之中／发而中节」是什么关系？是不是「中」从<strong>体用</strong>走到了<strong>时间</strong>？</li><li>「无忌惮」——反中庸的根，是认识问题（不懂）还是敬畏问题（不怕）？在我身上更像哪一种？</li><li>如果中庸是「随时处中」，它会不会滑向没有原则？我怎样分辨「时中」与「骑墙」？</li><li>孔子把「君子／小人」放在一句里对举——我现在更靠哪一边？证据是什么？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-01">中庸·第1章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-03">中庸·第3章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',23))])}}});export{f as __pageData,z as default};
